from pathlib import Path
import json,hashlib,subprocess,datetime
out=Path(__file__).resolve().parents[1];r=json.load(open(out/'recipe-refinement.json'));t=json.load(open(out/'recipe-tests.json'));red=json.load(open(out/'recipe-red-result.json'));sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();assert red['exit']==101 and red['sources_unchanged'];assert all(sha(p)==h for p,h in red['source_hashes'].items());assert Path(r['owner']).read_text()==r['expected_l0'];p=Path(r['source']);assert p.read_text()==t['expected_with_tests'];assert p.read_text().count(r['old'])==1;p.write_text(p.read_text().replace(r['old'],r['new'],1));subprocess.run(['rustfmt','--edition','2021','--config-path',str(Path('rustfmt.toml').resolve()),'--config','skip_children=true',str(p)],check=True);(out/'recipe-applied.json').write_text(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source':str(p),'expected_after':p.read_text()},ensure_ascii=False,indent=2)+'\n');subprocess.run(['python3',str(out/'workers/seal_owned.py'),str(p)],check=True);subprocess.run(['python3',str(out/'workers/guard.py')],check=True)
